// trailBodyNotEmptyError refuses a write against a document that already has
// content, with neither overwrite:true nor a matching If-Match to demonstrate
// the caller knows what they're about to replace. This API's error body is a
// single {"error": string} (errors.go's apiError) with no separate
// machine-readable field, so the reason is embedded as a stable, greppable
// prefix — reusing reasonDocumentNotEmpty (editor_content.go), the same value
// editorContentPut returns for its own declined-write case — rather than
// inventing a second error response shape for one route.
//
// This is a hard 409, not editorContentPut's 200 isApplied:false no-op,
// because a CLI caller that never inspects the response body must not be able
// to mistake a declined write for one that landed: a status code it can't
// ignore, unlike a 200 it might.
//
// currentETag rides as an actual ETag header (huma.ErrorWithHeaders), not
// just named in prose: every other editorDocumentETag call site sits behind
// the platform sync_editor_documents grant, which this route's callers lack
// — so this response is the only place they can ever learn it.
func trailBodyNotEmptyError(currentETag string) error {
	err := huma.Error409Conflict(reasonDocumentNotEmpty +
		": trail body already has content; pass overwrite:true to replace it, or retry with If-Match set to this response's ETag header — a match satisfies this guard on its own")
	return huma.ErrorWithHeaders(err, http.Header{"ETag": []string{currentETag}})
}

// trailBodyResolveDocument resolves row's body document for a write, in the
// SAME order trailBodyDocumentForDetail (trails.go) reads it: the trail's
// LINKED document id first, falling back to EnsureTrailBodyDocument only when
// there is no link (or the linked row is gone). An imported trail keeps its
// legacy (PlanetScale) document_key verbatim, so writing the deterministic
// "trail:<id>:body" key instead would silently create (or target) the WRONG
// document — and under a non-overwrite write that mistake is permanent, since
// nothing later notices the trail has two body documents.
//
// The fallback calls EnsureTrailBodyDocument directly rather than checking
// the deterministic key itself first: Ensure already does that lookup, AND
// repairs repo_trails.body_editor_document_id if it finds the row unlinked —
// a shortcut here would silently skip that repair, leaving a trail whose
// deterministic-key document exists but was never linked stuck that way
// forever. Same shape trailBodyDocumentEnsure (trails.go) uses.
//
// Unlike the read path, a trail with no live document gets one minted here
// (no seed) rather than trailBodyDocumentForDetail's synthetic empty
// snapshot: a write handler needs a real row to write TO. This mirrors
// resolveTrailCreate/resolveTrailUpdate, which already call
// EnsureTrailBodyDocument unconditionally with no cross-cell placement guard
// — unlike the dedicated trailBodyDocumentEnsure route's IsSoleProcessingPlacement
// backstop, which exists specifically for that route's caller (a websocket
// bridge that can be misrouted to a non-primary cell after a routing
// regression), not as a universal rule for every document-minting write path.
func trailBodyResolveDocument(ctx context.Context, deps *RepoActivityDeps, row store.TrailDetailRow, actorAccountID string) (store.EditorDocument, error) {
	if row.BodyEditorDocumentID != "" {
		doc, ok, err := deps.Store.EditorDocumentByID(ctx, row.BodyEditorDocumentID)
		if err != nil {
			return store.EditorDocument{}, huma.Error500InternalServerError("store: editor document by id", err)
		}
		if ok {
			return doc, nil
		}
	}
	doc, _, err := deps.Store.EnsureTrailBodyDocument(ctx, store.EnsureTrailBodyDocumentInput{
		TrailID: row.ID, ActorAccountID: actorAccountID,
	})
	if err != nil {
		return store.EditorDocument{}, huma.Error500InternalServerError("store: ensure trail body document", err)

		return store.EditorDocument{}, huma.Error500InternalServerError("store: ensure trail body document", err)
	}
	return doc, nil
}

// trailBodyPutCore is both routes' shared handler.
func trailBodyPutCore(ctx context.Context, deps *RepoActivityDeps, numberRaw string, body trailBodyPutBody, ifMatch string) (*TrailBodyPutOutput, error) {
	rep, err := trailsRepoFromContext(ctx)
	if err != nil {
		return nil, err
	}
	row, err := resolveTrailByNumberParam(ctx, deps, rep.repoID, numberRaw)
	if err != nil {
		return nil, err
	}

	hasMarkdown := rawPresent(body.Markdown)
	hasContentJSON := rawPresent(body.ContentJSON)
	if hasMarkdown == hasContentJSON {
		return nil, huma.Error400BadRequest("exactly one of markdown/contentJson is required")
	}
	var contentJSON json.RawMessage
	if hasMarkdown {
		md, ok := rawAsString(body.Markdown)
		if !ok {
			return nil, huma.Error400BadRequest("markdown must be a string")
		}
		// Same cap trail create/update apply to their own Markdown body
		// (trails_write.go) — this route is their sibling write path, not the
		// runner's, whose own trailBodyMaxMarkdownBytes is a much tighter
		// sub-bound on AI-generated run output with no bearing on a human
		// writing a description.
		if len(md) > maxTrailBodyLength {
			return nil, huma.Error400BadRequest("markdown exceeds maximum length")
		}
		contentJSON = editorjson.MarkdownToEditorJSON(md)
	} else {
		contentJSON = body.ContentJSON
	}

	// The bound that actually holds, checked where both input arms have
	// converged on the document the engine will receive. Conversion expands
	// (ProseMirror JSON is more verbose than the Markdown it encodes), so the
	// input check above cannot stand in for this one — it is a cost guard that
	// refuses an oversized request before it pays for conversion, nothing more.
	// A future third input arm inherits this check instead of having to
	// remember its own.
	if len(contentJSON) > maxTrailBodyLength {
		return nil, huma.Error400BadRequest("body exceeds maximum length")
	}

	if deps.YjsEngine == nil {
		return nil, huma.Error503ServiceUnavailable("yjs engine is not configured")
	}

	// Attribution comes from the authenticated session, never the request
	// body (unlike editorContentPut's updatedByAccountId/updatedByActorRef) —
	// a caller must not be able to attribute a write to someone else.
	// callerAccountID also refuses an automation-shaped caller (403): this
	// route's audience is a person or an agent acting as one, and an
	// automation principal already has editorContentPut's trail-scoped grant
	// for this.
	actorAccountID, err := callerAccountID(ctx)
	if err != nil {
		return nil, err
	}

	doc, err := trailBodyResolveDocument(ctx, deps, row, actorAccountID)
	if err != nil {
		return nil, err
	}

	// A supplied If-Match takes the non-empty guard out of play: either it
	// matches the document editorContentApplyCore is about to read (proof the
	// caller just looked, satisfying the same "did you know what you were
	// replacing" question overwrite:true answers by fiat) or it doesn't, in
	// which case the loop's If-Match check 412s before RefuseNonEmpty is ever
	// consulted. So this is not "If-Match bypasses the guard" — a mismatched
	// If-Match never reaches this document's content at all.
	ifMatchTrimmed := strings.TrimSpace(ifMatch)
	refuseNonEmpty := !body.Overwrite && ifMatchTrimmed == ""

	result, err := editorContentApplyCore(ctx, deps, editorContentApplyParams{
		Doc:                doc,
		ContentJSON:        contentJSON,
		IfMatch:            ifMatchTrimmed,
		RefuseNonEmpty:     refuseNonEmpty,
		UpdatedByAccountID: actorAccountID,
		SchemaVersion:      editorjson.SchemaVersion,
		OpAttr:             "trail_body_put",
	})
	if err != nil {
		return nil, err
	}
	if !result.Applied {
		return nil, trailBodyNotEmptyError(editorDocumentETag(result.Doc.UpdatedAt))
	}
	return &TrailBodyPutOutput{
		ETag: editorDocumentETag(result.Doc.UpdatedAt),
		Body: toTrailBodyDocumentJSON(result.Doc),
	}, nil
}

// registerTrailsBodyWrite wires the trail-body PUT routes onto the SAME
// requireTrailsWriteAccess[ByID] (repo.push) gate registerTrailsWrites uses —
// this route's authorization question ("can this account write this trail?")
// is identical to every other trail write, not a variant of it.
func registerTrailsBodyWrite(api huma.API, deps *RepoActivityDeps) {
	hostGate := []opMiddleware{requireAuth(api, &deps.baseDeps), requireTrailsWriteAccess(api, deps)}
	byIDGate := []opMiddleware{requireAuth(api, &deps.baseDeps), requireTrailsWriteAccessByID(api, deps)}

	putOp := teamOp("trailsBodyPut", http.MethodPut,
		"/trails/{host}/{owner}/{repo}/{number}/body", "Replace a trail's body", "trails", hostGate)
	putOp.Errors = withExtraErrors(putOp.Errors,
		http.StatusBadRequest, http.StatusNotFound, http.StatusConflict,
		http.StatusPreconditionFailed, http.StatusUnprocessableEntity,
		http.StatusServiceUnavailable,
		// The mux-wide front-door throttle (router.go) can reject any route
		// before it ever reaches this handler, same as editorContentPut.
		http.StatusTooManyRequests)
	huma.Register(api, putOp,
		func(ctx context.Context, in *TrailBodyPutInput) (*TrailBodyPutOutput, error) {
			return trailBodyPutCore(ctx, deps, in.Number, in.Body, in.IfMatch)
		})

	putByIDOp := teamOp("trailsBodyPutByRepoID", http.MethodPut,
		"/repos/{repo_id}/trails/{number}/body", "Replace a trail's body (repo_id addressing)", "trails", byIDGate)
	putByIDOp.Errors = withExtraErrors(putByIDOp.Errors,
		http.StatusBadRequest, http.StatusNotFound, http.StatusConflict,
		http.StatusPreconditionFailed, http.StatusUnprocessableEntity,
		http.StatusServiceUnavailable,
		// Same front-door throttle as the host-addressed twin above.
		http.StatusTooManyRequests)
	huma.Register(api, putByIDOp,
		func(ctx context.Context, in *TrailBodyPutByRepoIDInput) (*TrailBodyPutOutput, error) {
			return trailBodyPutCore(ctx, deps, in.Number, in.Body, in.IfMatch)
		})
}

