// byte-identical in field order, message text, and status — EXCEPT the
// body-update branch always 503s (this service has no editor-collaboration
// DO; see the module doc on the spike's trail-update.ts).
func validateUpdateTrailBody(body trailUpdateBody, currentStatus string) *trailValidationError {
	hasBodyUpdate := rawPresent(body.Body)
	hasMetadataUpdate := rawPresent(body.Branch) || rawPresent(body.Base) || rawPresent(body.Status) ||
		rawPresent(body.Title) || rawPresent(body.Assignees) || rawPresent(body.Type) ||
		rawPresent(body.Priority) || rawPresent(body.RequestedReviewers)

