		// keeps an oversized body from being reported as "service
		// unavailable" when it was never going to be accepted regardless of
		// editor-collaboration wiring.
		if len(s) > maxTrailBodyLength {
			return &trailValidationError{http.StatusBadRequest, "Body exceeds maximum length"}
		}
